const (
	maxTranscriptionAudioSizeBytes = 25 * MebiByte
	maxTranscriptionFilenameLength = 255
)

var supportedTranscriptionContentTypes = map[string]bool{
	"audio/aac":    true,
	"audio/aiff":   true,
	"audio/flac":   true,
	"audio/mpeg":   true,
	"audio/mp3":    true,
	"audio/mp4":    true,
	"audio/mpga":   true,
	"audio/ogg":    true,
	"audio/wav":    true,
	"audio/x-wav":  true,
	"audio/x-flac": true,
	"audio/x-m4a":  true,
	"audio/webm":   true,
	"video/mp4":    true,
	"video/mpeg":   true,
	"video/webm":   true,
}

// Transcribe transcribes an audio file using an instance AI provider.
func (s *APIV1Service) Transcribe(ctx context.Context, request *v1pb.TranscribeRequest) (*v1pb.TranscribeResponse, error) {
	user, err := s.fetchCurrentUser(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
	}
	if user == nil {
		return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
	}

	if request.Audio == nil {
		return nil, status.Errorf(codes.InvalidArgument, "audio is required")
	}
	if request.Audio.GetUri() != "" {
		return nil, status.Errorf(codes.InvalidArgument, "audio uri is not supported")
	}
	content := request.Audio.GetContent()
	if len(content) == 0 {
		return nil, status.Errorf(codes.InvalidArgument, "audio content is required")
	}
	if len(content) > maxTranscriptionAudioSizeBytes {
		return nil, status.Errorf(codes.InvalidArgument, "audio file is too large; maximum size is 25 MiB")
	}
	filename := strings.TrimSpace(request.Audio.GetFilename())
	if len(filename) > maxTranscriptionFilenameLength {
		return nil, status.Errorf(codes.InvalidArgument, "filename is too long; maximum length is %d characters", maxTranscriptionFilenameLength)
	}
	contentType := strings.TrimSpace(request.Audio.GetContentType())
	if contentType == "" {
		contentType = http.DetectContentType(content)
	}
	if !isSupportedTranscriptionContentType(contentType) {
		return nil, status.Errorf(codes.InvalidArgument, "audio content type %q is not supported", contentType)
	}

package scheduler

import (
	"context"
	"slices"
	"time"

	"github.com/pkg/errors"
)

// Middleware wraps a JobHandler to add cross-cutting behavior.
type Middleware func(JobHandler) JobHandler

// Chain combines multiple middleware into a single middleware.
// Middleware are applied in the order they're provided (left to right).
func Chain(middlewares ...Middleware) Middleware {
	return func(handler JobHandler) JobHandler {
		// Apply middleware in reverse order so first middleware wraps outermost
		for _, middleware := range slices.Backward(middlewares) {
			handler = middleware(handler)
		}
		return handler
	}
}

// Recovery recovers from panics in job handlers and converts them to errors.
func Recovery(onPanic func(jobName string, recovered interface{})) Middleware {
	return func(next JobHandler) JobHandler {
		return func(ctx context.Context) (err error) {
			defer func() {
				if r := recover(); r != nil {
					jobName := getJobName(ctx)
					if onPanic != nil {
						onPanic(jobName, r)
					}
					err = errors.Errorf("job %q panicked: %v", jobName, r)
				}
			}()
			return next(ctx)
		}
	}
}

// Logger is a minimal logging interface.
type Logger interface {
	Info(msg string, args ...interface{})
	Error(msg string, args ...interface{})
}

// Logging adds execution logging to jobs.
func Logging(logger Logger) Middleware {
	return func(next JobHandler) JobHandler {
		return func(ctx context.Context) error {
			jobName := getJobName(ctx)
			start := time.Now()

			logger.Info("Job started", "job", jobName)

			err := next(ctx)
			duration := time.Since(start)

			if err != nil {
				logger.Error("Job failed", "job", jobName, "duration", duration, "error", err)
			} else {
				logger.Info("Job completed", "job", jobName, "duration", duration)
			}

			return err
		}
	}
}

// Timeout wraps a job handler with a timeout.
func Timeout(duration time.Duration) Middleware {
	return func(next JobHandler) JobHandler {
		return func(ctx context.Context) error {
			ctx, cancel := context.WithTimeout(ctx, duration)
			defer cancel()

			done := make(chan error, 1)
			go func() {
				done <- next(ctx)
			}()

			select {
			case err := <-done:
				return err
			case <-ctx.Done():
				return errors.Errorf("job %q timed out after %v", getJobName(ctx), duration)
			}
		}
	}
}

// Context keys for job metadata.
type contextKey int

const (
	jobNameKey contextKey = iota
)

// withJobName adds the job name to the context.
func withJobName(ctx context.Context, name string) context.Context {
	return context.WithValue(ctx, jobNameKey, name)
}

// getJobName retrieves the job name from the context.
func getJobName(ctx context.Context) string {
	if name, ok := ctx.Value(jobNameKey).(string); ok {
		return name
	}
	return "unknown"
}

// GetJobName retrieves the job name from the context (public API).
// Returns empty string if not found.
//
//nolint:revive // GetJobName is the public API, getJobName is internal
func GetJobName(ctx context.Context) string {
	return getJobName(ctx)
}

package v1

import (
	"context"

	"golang.org/x/crypto/bcrypt"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
